<script setup lang="ts">
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowPathIcon } from '@heroicons/vue/24/outline'
import PageHeading from '../components/PageHeading.vue'
import TrendChart from '../components/TrendChart.vue'
import ErrorsTable from '../components/ErrorsTable.vue'
import InvestigationFilters from '../components/InvestigationFilters.vue'
import { activityLabel } from '../composables/collaboration'
import { bootstrap } from '../composables/api'
import { useInvestigation, queryString, date, zone } from '../composables/investigation'
import type { OverviewResult } from '../types'
const search=ref(''), status=ref('unresolved'),router=useRouter()
function openInbox(){router.push({path:'/errors',query:{...route.query,search:search.value||undefined,status:status.value}})}
const route=useRoute(),{data,loading,error,reload}=useInvestigation<OverviewResult>(()=>'/overview?'+queryString(route.query))
</script>
<template><PageHeading title="Overview" subtitle="Captured exceptions across this application"><InvestigationFilters :environments="data?.errors.environments"/><button class="button icon-button" aria-label="Refresh overview" :disabled="loading" @click="reload"><ArrowPathIcon/></button></PageHeading><div v-if="!bootstrap?.capture_status?.source_enabled || !bootstrap?.capture_status?.last_received_at || bootstrap?.capture_status?.failed || bootstrap?.capture_status?.pending" class="notice warning"><p>{{ !bootstrap?.capture_status?.source_enabled?'Capture is disabled. Review recording and watcher configuration.':!bootstrap?.capture_status?.last_received_at?'Capture has not been verified. An empty overview is not proof of application health.':bootstrap.capture_status.failed?`${bootstrap.capture_status.failed} capture items failed. Review system health.`:`${bootstrap.capture_status.pending} captures are waiting for processing. Counts may be incomplete.` }} <RouterLink to="/setup" class="text-link">Review setup</RouterLink></p></div><div v-if="error" class="notice danger" role="alert">{{ error }} <button class="button" @click="reload">Try again</button></div><p v-if="loading" role="status" class="loading-message">Loading captured errors…</p><template v-if="data"><div class="metrics-strip"><div><span>Captured occurrences</span><strong>{{ data.totals.occurrences }}</strong></div><div><span>New error groups</span><strong>{{ data.totals.new_groups }}</strong></div><div><span>Regressions</span><strong>{{ data.totals.regressions }}</strong></div></div><TrendChart :buckets="data.buckets"/><div class="section-heading attention-heading"><h2>Errors needing attention</h2><RouterLink :to="{path:'/errors',query:route.query}" class="text-link">View all errors</RouterLink></div><form class="attention-search" @submit.prevent="openInbox"><input v-model="search" type="search" aria-label="Search exception class or message" aria-describedby="overview-search-history" placeholder="Search exception class or message"><select v-model="status" aria-label="Open error status"><option v-for="s in ['unresolved','resolved','ignored','snoozed']" :key="s" :value="s">{{s}}</option></select><button class="button">Search errors</button></form><p id="overview-search-history" class="search-disclosure">Search terms appear in authenticated URLs and browser history.</p><ErrorsTable :items="data.errors.items.slice(0,10)" :range="data.window.range" compact/><div class="overview-secondary"><section><h2>Recent activity</h2><ul class="activity-list"><li v-for="(a,i) in data.activity" :key="i"><RouterLink :to="'/errors/'+a.issue_id">{{activityLabel(a.type)}} · {{ a.summary }}</RouterLink><time>{{ date(a.at) }}</time></li><li v-if="!data.activity.length">No recent activity.</li></ul></section><section><h2>Monitoring health</h2><p>{{ bootstrap?.capture_status?.pending??0 }} pending · {{ bootstrap?.capture_status?.failed??0 }} failed captures</p><p class="help">Last processing: {{ date(bootstrap?.capture_status?.last_processed_at) }}. A past observation does not prove a currently running worker.</p><p class="help">{{ data.delivery.detail }}</p><p v-if="data.delivery.observations" class="help">{{data.delivery.observations.pending}} pending deliveries · {{data.delivery.observations.failed}} failed · {{data.delivery.observations.needs_review}} require review</p><RouterLink v-if="data.delivery.state==='available'" to="/alerts/history" class="text-link">Delivery history</RouterLink><RouterLink v-if="bootstrap?.capabilities.manage" to="/settings/health" class="text-link">System health</RouterLink></section></div><p class="data-caption">Data as of {{ date(data.window.as_of) }} · {{ zone() }}<br>{{ data.window.coverage }}</p></template></template>
